import React, { useState, useEffect } from 'react';
import axios from 'axios';

const User = () => {
    const [rows, setRows] = useState([]);
    const [query, setQuery] = useState('');
    const [deleteId, setDeleteId] = useState(null); // Track the ID to delete
    const [showConfirm, setShowConfirm] = useState(false); // Show confirmation dialog

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await axios(`http://127.0.0.1:5000/users`);
                setRows(result.data);
            } catch (error) {
                alert('Gagal memuat data pengguna.');
            }
        };
        fetchData();
    }, [query]);

    const handleDelete = async (id) => {
        try {
            await axios.delete(`/api/user/hapus/${id}`);
            setRows((prevRows) => prevRows.filter((row) => row.kode_user !== id));
            setShowConfirm(false);
        } catch (error) {
            alert('Gagal menghapus data pengguna.');
        }
    };

    return (
        <div className="page-header">
            <h1>Data User</h1>
            <div className="panel panel-default">
                <div className="panel-heading">
                    <form className="form-inline">
                        <input type="hidden" name="m" value="user" />
                        <div className="form-group">
                            <input
                                className="form-control"
                                type="text"
                                placeholder="Pencarian..."
                                value={query}
                                onChange={(e) => setQuery(e.target.value)}
                            />
                        </div>
                        <div className="form-group">
                            <button className="btn btn-success" type="button" onClick={() => setQuery('')}>
                                <span className="glyphicon glyphicon-refresh"></span> Cari
                            </button>
                        </div>
                        <div className="form-group">
                            <a className="btn btn-primary" href="/user/tambah">
                                <span className="glyphicon glyphicon-plus"></span> Tambah
                            </a>
                        </div>
                    </form>
                </div>
                <div className="table-responsive">
                    <table className="table table-bordered table-hover table-striped">
                        <thead>
                            <tr>
                                <th>No</th>
                                <th>Kode</th>
                                <th>Nama</th>
                                <th>User</th>
                                <th>Level</th>
                                <th>Aksi</th>
                            </tr>
                        </thead>
                        <tbody>
                            {rows.map((row, index) => (
                                <tr key={row.kode_user}>
                                    <td>{index + 1}</td>
                                    <td>{row.kode_user}</td>
                                    <td>{row.nama_user}</td>
                                    <td>{row.user}</td>
                                    <td>{row.level}</td>
                                    <td>
                                        <a className="btn btn-xs btn-warning" href={`/user/ubah/${row.kode_user}`}>
                                            <span className="glyphicon glyphicon-edit"></span>
                                        </a>
                                        <button
                                            className="btn btn-xs btn-danger"
                                            onClick={() => {
                                                setDeleteId(row.kode_user);
                                                setShowConfirm(true);
                                            }}
                                        >
                                            <span className="glyphicon glyphicon-trash"></span>
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            {showConfirm && (
                <div className="modal" style={{ display: 'block', backgroundColor: 'rgba(0,0,0,0.5)' }}>
                    <div className="modal-dialog">
                        <div className="modal-content">
                            <div className="modal-header">
                                <h4 className="modal-title">Konfirmasi</h4>
                                <button
                                    type="button"
                                    className="close"
                                    onClick={() => setShowConfirm(false)}
                                >
                                    &times;
                                </button>
                            </div>
                            <div className="modal-body">
                                <p>Apakah Anda yakin ingin menghapus data ini?</p>
                            </div>
                            <div className="modal-footer">
                                <button
                                    className="btn btn-danger"
                                    onClick={() => handleDelete(deleteId)}
                                >
                                    Hapus
                                </button>
                                <button
                                    className="btn btn-secondary"
                                    onClick={() => setShowConfirm(false)}
                                >
                                    Batal
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default User;
